import unittest

class TestDecryptionUtils(unittest.TestCase):
    def setUp(self):
        self.d = DecryptionUtils('key')

    def test_empty_encrypted_text(self):
        self.assertEqual(self.d.rail_fence_decipher('', 3), '')

    def test_single_rail(self):
        self.assertEqual(self.d.rail_fence_decipher('Hello, World!', 1), 'Hello, World!')

    def test_non_alphabetic_characters(self):
        self.assertEqual(self.d.rail_fence_decipher('Hoo!el,Wrdl l', 3), 'Hello, World!')

    def test_negative_number_of_rails(self):
        with self.assertRaises(ValueError):
            self.d.rail_fence_decipher('Hoo!el,Wrdl l', -3)

    def test_zero_number_of_rails(self):
        with self.assertRaises(ValueError):
            self.d.rail_fence_decipher('Hoo!el,Wrdl l', 0)

    def test_non_integer_number_of_rails(self):
        with self.assertRaises(TypeError):
            self.d.rail_fence_decipher('Hoo!el,Wrdl l', 3.5)

    def test_encrypted_text_length_not_divisible_by_rails(self):
        self.assertEqual(self.d.rail_fence_decipher('Hoo!el,Wrdl', 3), 'Hello, World!')

    def test_encrypted_text_with_spaces(self):
        self.assertEqual(self.d.rail_fence_decipher('Hoo!el, Wrdl l', 3), 'Hello, World!')

if __name__ == '__main__':
    unittest.main()
